using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Security.Principal;
using System.Text.Json;
record Marker(long Qpc,int Pid,int Session,string Sid,bool Administrator);
static class Program {
 static readonly JsonSerializerOptions Json=new(){WriteIndented=true};
 static bool Admin()=>new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);
 static string Sid=>WindowsIdentity.GetCurrent().User!.Value;
 static object? service,folder;
 static dynamic Folder(){service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service")!);dynamic s=service!;s.Connect();folder=s.GetFolder("\\");return folder!;}
 static dynamic Create(string name,string exe,string args){dynamic s=service!;dynamic d=s.NewTask(0);d.RegistrationInfo.Description="Temporary CursorShake startup experiment; removed by probe";d.Principal.UserId=Sid;d.Principal.LogonType=3;d.Principal.RunLevel=0;d.Settings.Enabled=true;d.Settings.AllowDemandStart=true;d.Settings.StartWhenAvailable=true;d.Settings.DisallowStartIfOnBatteries=false;d.Settings.StopIfGoingOnBatteries=false;d.Settings.RunOnlyIfNetworkAvailable=false;d.Settings.RunOnlyIfIdle=false;d.Settings.ExecutionTimeLimit="PT0S";d.Settings.MultipleInstances=2;dynamic t=d.Triggers.Create(9);t.UserId=Sid;t.Enabled=true;t.Delay="PT0S";dynamic a=d.Actions.Create(0);a.Path=exe;a.Arguments=args;dynamic f=folder!;return f.RegisterTaskDefinition(name,d,2,Sid,null,3,null);}
 static bool Exists(string name){try{dynamic f=folder!;var t=f.GetTask(name);return t!=null;}catch(Exception e)when((uint)e.HResult==0x80070002){return false;}}
 static void Delete(string name){if(!Exists(name))return;dynamic f=folder!;f.DeleteTask(name,0);if(Exists(name))throw new Exception("Task still registered: "+name);}
 static void Release(){if(folder!=null)Marshal.FinalReleaseComObject(folder);if(service!=null)Marshal.FinalReleaseComObject(service);}
 static void WaitFor(string p,int ms=20000){var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<ms){if(File.Exists(p))return;Thread.Sleep(25);}throw new TimeoutException(p);}
 static int Inner(string root){Folder();string name="CursorShakeProbe-Child-"+Guid.NewGuid().ToString("N");string marker=Path.Combine(root,"marker with spaces.json");bool removed=false;object? result=null;string? error=null;try{string dll=Path.Combine(AppContext.BaseDirectory,"StartupProbe.dll");dynamic task=Create(name,"D:\\Program Files\\dotnet\\dotnet.exe",$"\"{dll}\" --marker \"{marker}\"");File.WriteAllText(Path.Combine(root,"child-task.xml"),(string)task.Xml);long q=Stopwatch.GetTimestamp();task.Run(null);WaitFor(marker);var m=JsonSerializer.Deserialize<Marker>(File.ReadAllText(marker))!;result=new{RegisteredByAdministrator=Admin(),LaunchDelayMs=(m.Qpc-q)*1000.0/Stopwatch.Frequency,MarkerAdministrator=m.Administrator,SameUser=m.Sid==Sid,SameSession=m.Session==Process.GetCurrentProcess().SessionId,LogonType="InteractiveToken",RunLevel="LeastPrivilege",LogonDelay="PT0S",ExecutionTimeLimit="PT0S",AllowsBattery=true,RequiresNetwork=false,RequiresIdle=false,ExecutableWithSpaces=true,ArgumentsWithSpaces=true};}catch(Exception e){error=e.ToString();}finally{try{Delete(name);removed=true;}catch(Exception e){error+="\nCLEANUP: "+e;}File.WriteAllText(Path.Combine(root,"inner-result.json"),JsonSerializer.Serialize(new{Result=result,Error=error,TemporaryTaskRemoved=removed,ActualLogonLatencyTested=false},Json));Release();}return error==null?0:1;}
 static int Outer(string root){if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("Use an empty artifact directory");Directory.CreateDirectory(root);Folder();string name="CursorShakeProbe-Launcher-"+Guid.NewGuid().ToString("N");bool removed=false;try{dynamic task=Create(name,Environment.ProcessPath!,$"--inner \"{root}\"");task.Run(null);WaitFor(Path.Combine(root,"inner-result.json"),30000);Console.WriteLine(File.ReadAllText(Path.Combine(root,"inner-result.json")));return 0;}finally{Delete(name);removed=true;File.WriteAllText(Path.Combine(root,"outer-result.json"),JsonSerializer.Serialize(new{TemporaryTaskRemoved=removed,ParentAdministrator=Admin(),ActualLogonLatencyTested=false},Json));Release();}}
 [STAThread]static int Main(string[] a){try{if(a[0]=="--marker"){var m=new Marker(Stopwatch.GetTimestamp(),Environment.ProcessId,Process.GetCurrentProcess().SessionId,Sid,Admin());File.WriteAllText(a[1],JsonSerializer.Serialize(m,Json));return 0;}if(a[0]=="--inner")return Inner(a[1]);return Outer(Path.GetFullPath(a[0]));}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
